<?php
if (session_status() === PHP_SESSION_NONE) {
    session_start();
}

$languageFile = __DIR__ . '/../languages/lang.docs';
$languageLines = file($languageFile, FILE_IGNORE_NEW_LINES | FILE_SKIP_EMPTY_LINES);
if ($languageLines === false) {
    throw new RuntimeException('Unable to read the available languages list.');
}

$available_languages = [];
foreach ($languageLines as $languageLine) {
    if (preg_match('/^([A-Za-z0-9-]+):\s*(.+)$/', trim($languageLine), $matches)) {
        $available_languages[$matches[1]] = trim($matches[2]);
    }
}

$requested_language = $_GET['lang'] ?? $_POST['lang'] ?? null;
if (is_string($requested_language) && (isset($available_languages[$requested_language]) || in_array($requested_language, ['ja', 'en'], true))) {
    $_SESSION['lang'] = $requested_language;
}

$current_lang = $_SESSION['lang'] ?? 'ja-JP';
if (!is_string($current_lang)) {
    $current_lang = 'ja-JP';
}
if ($current_lang === 'ja') {
    $current_lang = 'ja-JP';
} elseif ($current_lang === 'en') {
    $current_lang = 'en-US';
}
if (!isset($available_languages[$current_lang])) {
    $current_lang = 'ja-JP';
}
$_SESSION['lang'] = $current_lang;
$text_direction = in_array(strtolower(strtok($current_lang, '-')), ['ar', 'dv', 'fa', 'he', 'ku', 'ps', 'ur'], true)
    ? 'rtl'
    : 'ltr';

