// 翻訳用ヘルパー関数
function __($key) {
    global $translations, $current_lang;
    $language = strtolower(strtok($current_lang, '-'));
    return $translations[$current_lang][$key]
        ?? $translations[$language][$key]
        ?? $translations['en'][$key]
        ?? $key;
}
?>